package com.volna.inventory_service.entity;import jakarta.persistence.*;import java.math.BigDecimal;@Entity @Table(name="inventory_purchase_order_items") public class PurchaseOrderItem { @Id @GeneratedValue(strategy=GenerationType.IDENTITY)Long id;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="purchase_order_id",nullable=false)PurchaseOrder purchaseOrder;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="inventory_item_id",nullable=false)InventoryItem inventoryItem;@Column(nullable=false,precision=12,scale=2)BigDecimal quantity;@Column(name="unit_price",nullable=false,precision=12,scale=2)BigDecimal unitPrice;public void setPurchaseOrder(PurchaseOrder v){purchaseOrder=v;}public InventoryItem getInventoryItem(){return inventoryItem;}public void setInventoryItem(InventoryItem v){inventoryItem=v;}public BigDecimal getQuantity(){return quantity;}public void setQuantity(BigDecimal v){quantity=v;}public BigDecimal getUnitPrice(){return unitPrice;}public void setUnitPrice(BigDecimal v){unitPrice=v;} }
